INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2268, 'កសិដ្ឋានមួយមានចំណូល \(3\,800\,000\) ៛ ក្នុងមួយខែ ក្នុងនោះលក់មាន់ \(\dfrac{1}{4}\) លក់ជ្រូក \(\dfrac{2}{4}\) ហើយនៅសល់ពីលក់ទា។ ចំណូលពីការលក់ទាស្មើប៉ុន្មានរៀល?', NULL, '["\\(475\\,000\\) ៛", "\\(950\\,000\\) ៛", "\\(1\\,900\\,000\\) ៛", "\\(2\\,850\\,000\\) ៛"]', 1, NULL, 3, 'mcq', '\(1 - \dfrac{1}{4} - \dfrac{2}{4} = \dfrac{1}{4}\) \(\dfrac{1}{4} \times 3\,800\,000 = 950\,000\)។', 'ប្រភាគ', 'pisa', 1, '7', 'ប្រភាគ', NULL, 0);
