INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2273, 'ម្តាយចែកប្រាក់ឱ្យកូន \(4\) នាក់ ៖ កូនទី ១ បាន \(\dfrac{1}{6}\) ទី ២ បាន \(\dfrac{1}{4}\) ទី ៣ បាន \(\dfrac{1}{2}\) នៃប្រាក់ ហើយកូនទី ៤ បាន \(30\,000\) ៛។ គណនាប្រាក់ដែលម្តាយយកមកចែក និងប្រាក់ដែលកូននីមួយៗបាន។', NULL, '[]', 0, NULL, 5, 'writing', 'កូនទី ១-៣ បានសរុប \(\dfrac{1}{6} + \dfrac{1}{4} + \dfrac{1}{2} = \dfrac{11}{12}\) (1 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2274, 'សន្សំប្រាក់ ៖ \(\dfrac{2}{3}\) នៃចំណូលចំណាយលើតម្រូវការ ហើយ \(\dfrac{1}{3}\) សម្រាប់សន្សំ។ បើសន្សំបាន \(300\,000\) ៛ ក្នុងមួយខែ។ ក. រកចំណូលសរុប។ ខ. រកប្រាក់ចំណាយ។ គ. ក្នុងមួយឆ្នាំសន្សំបានប៉ុន្មាន?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(300\,000 \div \dfrac{1}{3} = 900\,000\) ៛ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2275, 'ចិន្តាអានសៀវភៅមួយដល់ទំព័រ \(377\) ដែលជា \(\dfrac{13}{15}\) នៃសៀវភៅ។ ក. សៀវភៅមានប៉ុន្មានទំព័រ? ខ. នៅសល់ប៉ុន្មានទំព័រត្រូវអាន? គ. \(\dfrac{13}{15}\) ជាប៉ុន្មានភាគរយប្រហែល?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(377 \div \dfrac{13}{15} = 377 \times \dfrac{15}{13} = 435\) ទំព័រ (2 ពិន្ទុ)
INSERT INTO test_questions (test_id, order_no, stem_text, image_key, options_json, correct_index, alt_correct_index, points, kind, solution_text, topic, level, shuffle, grade, lesson, params, cancelled) VALUES (10, 2276, 'កសិដ្ឋានមួយទទួលចំណូល \(3\,800\,000\) ៛ ក្នុងមួយខែ ៖ លក់មាន់ \(\dfrac{1}{4}\) លក់ជ្រូក \(\dfrac{2}{4}\) ហើយនៅសល់ពីលក់ទា។ ក. ទាបានប៉ុន្មានភាគនៃចំណូល? ខ. ចំណូលពីមាន់ ជ្រូក ទា ជាប៉ុន្មានរៀលរៀងគ្នា?', NULL, '[]', 0, NULL, 5, 'writing', 'ក. \(1 - \dfrac{1}{4} - \dfrac{2}{4} = \dfrac{1}{4}\) (2 ពិន្ទុ)
